[InitializeOnLoad]public static class CoastalPineFullPreview{static CoastalPineFullPreview(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("CoastalPineFullPreview.request"))return;File.Delete("CoastalPineFullPreview.request");var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var root=scene.GetRootGameObjects().Single(g=>g.name=="Coastal Rocky Terrain");float best=float.MaxValue;Vector3 anchor=Vector3.zero;float height=15;foreach(var f in root.GetComponentsInChildren<MeshFilter>()){if(f.name!="Detailed"||!f.transform.parent.name.StartsWith("Pine_"))continue;var mesh=f.sharedMesh;var p=mesh.vertices;var wind=new List<Vector4>();mesh.GetUVs(1,wind);var groups=new Dictionary<Vector2,List<int>>();for(int i=0;i<p.Length;i++){var key=new Vector2(wind[i].y,wind[i].z);if(!groups.ContainsKey(key))groups[key]=new List<int>();groups[key].Add(i);}foreach(var g in groups){float d=Vector2.Distance(g.Key,new Vector2(830,180));if(d<best&&g.Key.x>815){best=d;anchor=new Vector3(g.Key.x,g.Value.Min(i=>p[i].y),g.Key.y);height=g.Value.Max(i=>p[i].y)-anchor.y;}}}typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{scene,anchor+new Vector3(-height*.8f,height*.54f,-height*1.25f),anchor+Vector3.up*height*.52f,"Reference-Pine-Full-Tree-Review"});}}
